<div class="form-grid"><div class="form-field full-field"><label for="product_id">Pilih produk <span class="required">*</span></label><select class="form-control" id="product_id" name="product_id" required><option value="">Pilih produk yang ditransaksikan</option><?php $__currentLoopData = $products; $__env->addLoop($__currentLoopData); foreach($__currentLoopData as $product): $__env->incrementLoopIndices(); $loop = $__env->getLastLoop(); ?><option value="<?php echo e($product->id); ?>" data-stock="<?php echo e($product->stock); ?>" data-unit="<?php echo e($product->unit); ?>" <?php if($selectedProduct == $product->id): echo 'selected'; endif; ?>><?php echo e($product->sku); ?> — <?php echo e($product->name); ?> (stok: <?php echo e($product->stock); ?> <?php echo e($product->unit); ?>)</option><?php endforeach; $__env->popLoop(); $loop = $__env->getLastLoop(); ?></select><small id="productStockHint">Saldo terkini akan ditampilkan setelah produk dipilih.</small></div>
<div class="form-field"><label for="quantity">Jumlah <span class="required">*</span></label><input class="form-control" type="number" id="quantity" name="quantity" min="1" max="100000000" required value="<?php echo e(old('quantity', $movement->quantity ?? 1)); ?>"></div>
<div class="form-field"><label for="movement_date">Tanggal transaksi <span class="required">*</span></label><input class="form-control" type="date" id="movement_date" name="movement_date" max="<?php echo e(now()->toDateString()); ?>" required value="<?php echo e(old('movement_date', isset($movement) ? $movement->movement_date->toDateString() : now()->toDateString())); ?>"></div>
<div class="form-field full-field"><label for="reference">Nomor referensi</label><input class="form-control" id="reference" name="reference" maxlength="60" value="<?php echo e(old('reference', $movement->reference ?? '')); ?>" placeholder="Contoh: PO-2026-001 / DO-2026-012"></div>
<div class="form-field full-field"><label for="notes">Catatan</label><textarea class="form-control" id="notes" name="notes" rows="3" maxlength="1000" placeholder="Keterangan tambahan transaksi..."><?php echo e(old('notes', $movement->notes ?? '')); ?></textarea></div></div>
